{
  "version": 1,
  "defaultSuite": "smoke",
  "suites": {
    "smoke": [
      {
        "action": "assert",
        "expr": "typeof window.aibox.tools === 'object' && typeof window.aibox.tools.call === 'function'",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(async () => { const v = await window.aibox.access.explain({ tool: 'viddl_inspect' }); if (!v || !v.allowed) throw new Error('viddl_inspect not granted: ' + JSON.stringify(v)); return 'extractor reachable' })()"
      },
      {
        "action": "assert",
        "expr": "!document.body.innerText.includes('解析能力不可用')",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "!document.body.innerText.includes('私密')",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim().includes('添加')); if (!b) throw new Error('add entry point missing'); b.click(); return 'opened' })()"
      },
      { "action": "wait", "ms": 600 },
      {
        "action": "assert",
        "expr": "!!document.querySelector('input[placeholder*=\"视频页面\"]')",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(async () => { const r = await window.aibox.tools.call({ name: 'viddl_jobs', arguments: { action: 'list' } }); if (!r || r.isError) throw new Error('viddl_jobs list failed: ' + JSON.stringify(r)); return 'library reachable' })()"
      }
    ],
    "queue": [
      {
        "action": "eval",
        "expr": "(async () => { const items = await window.aibox.download.list({}); return 'queue readable: ' + items.length + ' rows' })()"
      }
    ]
  }
}

// 视频下载（com.aibox.viddl）—— 解析 / 画质 / 离线资料库。
//
// ## 边界：这个应用做 UI 与策略，不做解析也不做传输
//
//  · **来源解析**（B 站 / YouTube / HLS / 通用页嗅探）是领域逻辑，五个站点适配器留在原生侧，
//    本应用经 `aibox.tools` 遥控 `viddl_inspect`；
//  · **传输**在宿主的两条后台 session 上跑（直链/DASH 轨道走下载引擎、HLS 走 AVAssetDownload），
//    本应用只拿 jobId 和只读进度；
//  · **画质选择**与**资料库排序**才是本应用的东西——判据把它们判为「策略归应用」：
//    同一个视频，两个应用可以默认选不同档且都对。
//
// 进度有两个来源，同源不冲突：`viddl_jobs list`（高层 job 状态机，权威）+
// `aibox.download.list()`（统一队列的结构化字节/速度，**含 HLS 那一半**——补充源已并进来）。
// 前者定「有哪些任务、到哪一步」，后者补「多少字节、多快」。
//
// ⚠️ 没有「私密视频」。该功能连同 Face ID 门已整体裁撤（2026-08-03 用户裁定）。

import React from 'react'
import { THEME_CSS, C, SPACE, formatBytes, formatSpeed, stateColor } from './components/theme.js'
import { Button, Card, EmptyState, Notice, ProgressBar, SectionHeader, IconButton } from './components/primitives.jsx'
import Icon from './components/Icon.jsx'
import InspectSheet from './components/InspectSheet.jsx'
import {
  capabilities, onEvent, onNamespaceEvent, queue, readClipboard, tap, toolAllowed,
} from './lib/host.js'
import { fetchVideo, inspectVideo, libraryAction, registerActions, uiHooks } from './lib/actions.js'

// 无头执行时页面不挂载任何组件——注册必须发生在模块求值期。
registerActions()

const TABS = [
  { id: 'library', title: '资料库', icon: 'film', selectedIcon: 'film.fill' },
  { id: 'downloading', title: '下载中', icon: 'arrow.down.circle', selectedIcon: 'arrow.down.circle.fill' },
]

const DONE_STATES = ['completed']
const FAIL_STATES = ['failed', 'cancelled']

function useThemeSetup() {
  React.useEffect(() => {
    if (document.getElementById('__vd_css__')) return
    const style = document.createElement('style')
    style.id = '__vd_css__'
    style.textContent = THEME_CSS
    document.head.appendChild(style)
  }, [])
}

/** 高层 job 表 + 统一队列的字节明细。两者按 groupId(=jobId) 对齐。 */
function useJobs() {
  const [jobs, setJobs] = React.useState([])
  const [bytes, setBytes] = React.useState({})
  const [loaded, setLoaded] = React.useState(false)

  const refresh = React.useCallback(async () => {
    const result = await libraryAction({ action: 'list' })
    setJobs(result.jobs || [])
    setLoaded(true)
  }, [])

  const refreshBytes = React.useCallback(async () => {
    const items = await queue.list()
    // 一个 job 可能有多条轨道（DASH 双轨），按 groupId 聚合；HLS 只有一条（补充源投影的那条）。
    const map = {}
    for (const item of items) {
      const key = item.groupId || item.taskId
      const row = map[key] || { received: 0, total: 0, speed: 0, known: true }
      row.received += item.bytesReceived || 0
      if (item.totalBytes) row.total += item.totalBytes
      else row.known = false
      row.speed += item.speed || 0
      map[key] = row
    }
    setBytes(map)
  }, [])

  React.useEffect(() => {
    let alive = true
    let poll = null
    let off = null
    const boot = async () => {
      await refresh()
      await refreshBytes()
      const pushed = await queue.subscribe()
      if (!alive) return
      off = onEvent('download.progress', () => { refreshBytes() })
      // job 状态机没有事件通道（`viddl_jobs` 是工具不是能力），所以状态仍要轮询；
      // 但**字节/速度走事件**，于是轮询周期可以放到 2.5s 而不牺牲进度条的顺滑。
      poll = setInterval(() => { refresh(); if (!pushed) refreshBytes() }, pushed ? 2500 : 1200)
    }
    boot()
    return () => {
      alive = false
      if (poll) clearInterval(poll)
      if (off) off()
      queue.unsubscribe()
    }
  }, [refresh, refreshBytes])

  return { jobs, bytes, loaded, refresh }
}

function JobRow({ job, detail, onPause, onResume, onCancel, onRetry, onPlay, onExport }) {
  const done = DONE_STATES.includes(job.state)
  const failed = FAIL_STATES.includes(job.state)
  const active = !done && !failed
  const color = stateColor(job.state === 'downloading' || job.state === 'processing' ? 'running'
    : done ? 'completed' : failed ? 'failed' : job.state)
  const parts = []
  if (detail && detail.received) {
    parts.push(detail.known && detail.total
      ? `${formatBytes(detail.received)} / ${formatBytes(detail.total)}`
      : formatBytes(detail.received))
  }
  if (active && detail && detail.speed) parts.push(formatSpeed(detail.speed))
  if (job.source) parts.push(job.source)
  if (failed) parts.push(job.state === 'cancelled' ? '已取消' : '失败')
  if (done && job.outputName) parts.push(job.outputName)

  return (
    <div data-row-id={job.jobId} style={{ padding: `${SPACE.s3}px ${SPACE.s4}px` }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3 }}>
        <div style={{
          width: 44, height: 30, borderRadius: 6, background: C.track,
          display: 'flex', alignItems: 'center', justifyContent: 'center', color,
        }}>
          <Icon name={done ? 'play.rectangle' : failed ? 'exclamationmark.circle' : 'arrow.down.circle'} size={18} />
        </div>
        <div style={{ flex: '1 1 auto', minWidth: 0 }}>
          <div style={{
            fontSize: 15, fontWeight: 500,
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          }}>{job.title}</div>
          <div style={{
            fontSize: 12.5, color: failed ? C.failed : C.muted, marginTop: 2,
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          }}>{parts.join(' · ') || job.state}</div>
        </div>
        {active && typeof job.fraction === 'number' ? (
          <span style={{ fontSize: 12.5, color: C.muted, fontVariantNumeric: 'tabular-nums' }}>
            {Math.round(job.fraction * 100)}%
          </span>
        ) : null}
        {job.state === 'downloading' ? <IconButton name="pause" onClick={() => onPause(job)} label="暂停" /> : null}
        {job.state === 'paused' ? <IconButton name="play" onClick={() => onResume(job)} label="继续" /> : null}
        {active ? <IconButton name="xmark" onClick={() => onCancel(job)} label="取消" /> : null}
        {failed ? <IconButton name="arrow.clockwise" onClick={() => onRetry(job)} label="重试" /> : null}
        {done ? <IconButton name="play" onClick={() => onPlay(job)} label="播放" /> : null}
        {done && job.outputName && /\.movpkg$/i.test(job.outputName)
          ? <IconButton name="square.and.arrow.down" onClick={() => onExport(job)} label="导出 mp4" />
          : null}
      </div>
      {active ? (
        <div style={{ marginTop: SPACE.s2, marginLeft: 44 + SPACE.s3 }}>
          <ProgressBar fraction={job.fraction} color={color} />
        </div>
      ) : null}
    </div>
  )
}

export default function App() {
  useThemeSetup()
  const [tab, setTab] = React.useState('library')
  const [shell, setShell] = React.useState({ tabsRendered: false, toolbarRendered: false })
  const [adding, setAdding] = React.useState(false)
  const [notice, setNotice] = React.useState(null)
  const [extractorReady, setExtractorReady] = React.useState(true)
  const { jobs, bytes, loaded, refresh } = useJobs()

  // 解析面不可用时（Lean 变体解链了 MODULE_VIDEODOWNLOAD）**整块入口不渲染**，
  // 而不是留一个点了报错的按钮——「合法留 ≠ 必须留」。
  React.useEffect(() => { toolAllowed('viddl_inspect').then(setExtractorReady) }, [])

  React.useEffect(() => {
    uiHooks.refresh = refresh
    return () => { uiHooks.refresh = null }
  }, [refresh])

  const done = jobs.filter((j) => DONE_STATES.includes(j.state))
  const running = jobs.filter((j) => !DONE_STATES.includes(j.state))
  const visible = tab === 'library' ? done : running

  const act = React.useCallback(async (action, jobId) => {
    tap('light')
    const result = await libraryAction({ action, jobId })
    if (!result.ok) setNotice({ tone: 'error', text: result.text || '操作失败' })
    await refresh()
  }, [refresh])

  const startDownload = React.useCallback(async (request) => {
    const result = await fetchVideo(request)
    setNotice(result.ok ? { tone: 'success', text: result.text } : { tone: 'error', text: result.text })
    if (result.ok) { tap('medium'); setTab('downloading') }
    await refresh()
  }, [refresh])

  // —— 宿主外壳接线 ——
  const addRef = React.useRef(null)
  addRef.current = () => setAdding(true)

  React.useEffect(() => {
    let cancelled = false
    const offs = []
    const wire = async () => {
      const api = window.aibox
      if (api && api.tabs && typeof api.tabs.getState === 'function') {
        try {
          const state = await api.tabs.getState()
          if (!cancelled && state && state.rendered) {
            setShell((c) => ({ ...c, tabsRendered: true }))
            if (state.selected) setTab(state.selected)
          }
        } catch (error) { /* 宿主没这能力：留给自绘 TabBar */ }
        offs.push(onNamespaceEvent('tabs', 'changed', (state) => {
          if (!state) return
          // `rendered` 会在挂载之后翻转（形态切换重发 changed），只判一次会永远多/少一条自绘条。
          const rendered = state.rendered !== false
          setShell((c) => (c.tabsRendered === rendered ? c : { ...c, tabsRendered: rendered }))
          if (state.selected) setTab(state.selected)
        }))
      }
      if (api && api.toolbar && typeof api.toolbar.getState === 'function') {
        try {
          const state = await api.toolbar.getState()
          if (!cancelled && state) setShell((c) => ({ ...c, toolbarRendered: state.rendered !== false }))
        } catch (error) { /* 同上 */ }
        offs.push(onNamespaceEvent('toolbar', 'invoke', (payload) => {
          if (payload && payload.id === 'add' && addRef.current) addRef.current()
        }))
      }
      offs.push(onEvent('lifecycle.foreground', () => { refresh() }))
    }
    wire()
    return () => { cancelled = true; offs.forEach((off) => off && off()) }
  }, [refresh])

  const runningCount = running.length
  React.useEffect(() => {
    const api = window.aibox
    const title = tab === 'library' ? '资料库' : '下载中'
    document.title = title
    if (api && api.navigation && typeof api.navigation.setTitle === 'function') {
      api.navigation.setTitle({ title }).catch(() => {})
    }
    if (api && api.toolbar && typeof api.toolbar.update === 'function') {
      api.toolbar.update({ items: { add: { hidden: !extractorReady } } }).catch(() => {})
    }
    if (api && api.tabs && typeof api.tabs.update === 'function') {
      api.tabs.update({
        items: { downloading: { badge: runningCount ? String(runningCount) : null } },
      }).catch(() => {})
    }
  }, [tab, runningCount, extractorReady])

  return (
    <div style={{ minHeight: '100vh', paddingBottom: shell.tabsRendered ? 0 : 76 }}>
      {!shell.toolbarRendered ? (
        <div style={{
          display: 'flex', alignItems: 'center', gap: SPACE.s2,
          padding: `calc(${SPACE.s3}px + env(safe-area-inset-top)) ${SPACE.s4}px ${SPACE.s3}px`,
        }}>
          <span style={{ fontSize: 22, fontWeight: 700 }}>{tab === 'library' ? '资料库' : '下载中'}</span>
          <div style={{ flex: '1 1 auto' }} />
          {extractorReady
            ? <Button kind="primary" icon="plus" onClick={() => setAdding(true)}>添加</Button>
            : null}
        </div>
      ) : null}

      <Notice text={notice && notice.text} tone={notice && notice.tone} onDismiss={() => setNotice(null)} />

      {!extractorReady ? (
        <div style={{ padding: `0 ${SPACE.s4}px` }}>
          <EmptyState
            icon="exclamationmark.circle"
            title="解析能力不可用"
            hint="这个宿主没有装视频下载模块，只能查看已经下好的内容，不能再解析新的链接。"
          />
        </div>
      ) : null}

      <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s5}px` }}>
        {!loaded ? null : visible.length === 0 ? (
          extractorReady ? (
            <EmptyState
              icon={tab === 'library' ? 'film' : 'arrow.down.circle'}
              title={tab === 'library' ? '资料库还是空的' : '没有进行中的下载'}
              hint={tab === 'library'
                ? '粘贴一个视频页面地址，先看清有哪些画质，再决定下哪一个。'
                : '下载在后台继续，退出这个小应用也不会中断。'}
              action={tab === 'library'
                ? <Button kind="primary" icon="plus" onClick={() => setAdding(true)}>添加视频</Button>
                : null}
            />
          ) : null
        ) : (
          <>
            <SectionHeader>{visible.length} 项</SectionHeader>
            <Card padding={0}>
              {visible.map((job, index) => (
                <div key={job.jobId} style={index ? { borderTop: `1px solid ${C.line}` } : undefined}>
                  <JobRow
                    job={job}
                    detail={bytes[job.jobId]}
                    onPause={(j) => act('pause', j.jobId)}
                    onResume={(j) => act('resume', j.jobId)}
                    onCancel={(j) => act('cancel', j.jobId)}
                    onRetry={(j) => act('retry', j.jobId)}
                    onPlay={(j) => act('play', j.jobId)}
                    onExport={(j) => act('export', j.jobId)}
                  />
                </div>
              ))}
            </Card>
          </>
        )}
      </div>

      {!shell.tabsRendered ? (
        <div style={{
          position: 'fixed', left: 0, right: 0, bottom: 0, zIndex: 40,
          display: 'flex', borderTop: `1px solid ${C.line}`, background: C.surface,
          paddingBottom: 'env(safe-area-inset-bottom)',
        }}>
          {TABS.map((row) => (
            <button
              key={row.id}
              type="button"
              onClick={() => { setTab(row.id); tap('light') }}
              style={{
                flex: '1 1 0', display: 'flex', flexDirection: 'column', alignItems: 'center',
                gap: 2, padding: '8px 0 6px', background: 'none', border: 'none', cursor: 'pointer',
                color: tab === row.id ? C.brand : C.muted,
              }}
            >
              <Icon name={tab === row.id ? row.selectedIcon : row.icon} size={22} />
              <span style={{ fontSize: 11 }}>{row.title}</span>
            </button>
          ))}
        </div>
      ) : null}

      <InspectSheet
        open={adding}
        onClose={() => setAdding(false)}
        onInspect={(url) => inspectVideo({ url })}
        onDownload={startDownload}
        onPaste={capabilities.clipboard ? readClipboard : null}
      />
    </div>
  )
}

// 「添加视频」面板：粘贴地址 → 解析 → **选画质** → 下载。
//
// 画质选择是这个应用的核心交互，也是判据里唯一判为「策略归应用」的那一格：
// 同一个视频，两个应用可以默认选不同档且**都对**（一个默认最高清、一个默认省流量）。
// 所以它必须在这里画出来，而不是让宿主替用户决定。

import React from 'react'
import Icon from './Icon.jsx'
import { Button, Chip, Sheet } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'

/** 从一段文本里抽第一个 http(s) 链接（分享过来的文字常常带一堆前后缀）。 */
export function firstURL(text) {
  const found = String(text || '').match(/https?:\/\/[^\s<>"')\]]+/)
  return found ? found[0].replace(/[.,;]+$/, '') : ''
}

function protoBadge(proto) {
  const label = { direct: '直链', hls: 'HLS', dash: 'DASH' }[proto] || proto
  return (
    <span style={{
      fontSize: 11, padding: '1px 6px', borderRadius: 4,
      border: `1px solid ${C.line}`, color: C.muted,
    }}>{label}</span>
  )
}

export default function InspectSheet({ open, onClose, onInspect, onDownload, onPaste }) {
  const [url, setUrl] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const [info, setInfo] = React.useState(null)
  const [formats, setFormats] = React.useState([])
  const [chosen, setChosen] = React.useState(null)
  const [audioOnly, setAudioOnly] = React.useState(false)
  const [error, setError] = React.useState('')

  React.useEffect(() => {
    if (!open) return
    setUrl(''); setInfo(null); setFormats([]); setChosen(null); setAudioOnly(false); setError('')
  }, [open])

  const inspect = async () => {
    const target = firstURL(url)
    if (!target) { setError('没找到 http(s) 链接。'); return }
    setBusy(true); setError('')
    const result = await onInspect(target)
    setBusy(false)
    if (!result.ok) { setError(result.text || result.error || '解析失败。'); return }
    setInfo(result.video)
    setFormats(result.formats || [])
    // 缺省选第一条——extractor 已按清晰度降序给出，第一条就是「最好的那个」。
    setChosen((result.formats && result.formats[0] && result.formats[0].id) || null)
    if (!result.formats || !result.formats.length) {
      // 解析成功但没有格式清单（部分直链就是这样）：仍然可以下，只是没得选。
      setError('')
    }
  }

  const start = async () => {
    const target = firstURL(url)
    if (!target) return
    setBusy(true)
    await onDownload({ url: target, formatId: chosen || undefined, audioOnly })
    setBusy(false)
    onClose()
  }

  return (
    <Sheet
      open={open}
      title="添加视频"
      onClose={onClose}
      footer={info ? (
        <Button kind="primary" block disabled={busy} onClick={start} icon="arrow.down.to.line">
          {audioOnly ? '只下音频' : '开始下载'}
        </Button>
      ) : (
        <Button kind="primary" block disabled={busy || !url.trim()} onClick={inspect} icon="magnifyingglass">
          {busy ? '解析中…' : '解析'}
        </Button>
      )}
    >
      <input
        value={url}
        onChange={(e) => { setUrl(e.target.value); setInfo(null); setFormats([]) }}
        placeholder="粘贴视频页面或直链地址"
        style={{
          width: '100%', boxSizing: 'border-box',
          padding: SPACE.s3, borderRadius: RADIUS.control,
          border: `1px solid ${C.line}`, background: 'transparent', fontSize: 14,
        }}
      />
      {onPaste ? (
        <div style={{ marginTop: SPACE.s2 }}>
          <Button
            icon="doc.on.clipboard"
            onClick={async () => { const t = await onPaste(); if (t) { setUrl(t); setInfo(null) } }}
          >从剪贴板粘贴</Button>
        </div>
      ) : null}

      {error ? (
        <div style={{ marginTop: SPACE.s3, fontSize: 13, color: C.failed, lineHeight: 1.5 }}>{error}</div>
      ) : null}

      {info ? (
        <div style={{ marginTop: SPACE.s4 }}>
          <div style={{ display: 'flex', gap: SPACE.s3 }}>
            {info.thumbnailURL ? (
              <img
                src={info.thumbnailURL}
                alt=""
                style={{ width: 96, height: 54, objectFit: 'cover', borderRadius: 8, background: C.track }}
              />
            ) : (
              <div style={{
                width: 96, height: 54, borderRadius: 8, background: C.track,
                display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.muted,
              }}><Icon name="film" size={22} /></div>
            )}
            <div style={{ flex: '1 1 auto', minWidth: 0 }}>
              <div style={{ fontSize: 15, fontWeight: 600, lineHeight: 1.35 }}>{info.title}</div>
              <div style={{ fontSize: 12.5, color: C.muted, marginTop: 3 }}>
                {[info.uploader, info.durationText, info.extractor].filter(Boolean).join(' · ')}
              </div>
            </div>
          </div>

          {formats.length ? (
            <>
              <div style={{ marginTop: SPACE.s4, fontSize: 13, fontWeight: 600, color: C.muted }}>画质</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: SPACE.s1, marginTop: SPACE.s2 }}>
                {formats.map((f) => (
                  <button
                    key={f.id}
                    type="button"
                    onClick={() => setChosen(f.id)}
                    style={{
                      display: 'flex', alignItems: 'center', gap: SPACE.s2, textAlign: 'left',
                      padding: `${SPACE.s2}px ${SPACE.s3}px`, borderRadius: RADIUS.control,
                      border: `1px solid ${chosen === f.id ? C.brand : C.line}`,
                      background: 'transparent', cursor: 'pointer', minHeight: 44,
